mapper.select:
SELECT ai.id, ai.asset_code, ai.category_id, ai.asset_name, ai.spec, ai.manufacturer, ai.unit, ai.price, ai.status, ai.create_user, ai.create_time, ai.update_time, ac3.category_name FROM asset_item ai LEFT JOIN asset_category ac3 ON ai.category_id = ac3.id LEFT JOIN asset_category ac2 ON ac3.parent_id = ac2.id LEFT JOIN asset_category ac1 ON ac2.parent_id = ac1.id WHERE 1=1
AND ai.asset_code LIKE CONCAT('%', #{assetCode}, '%')
AND ai.asset_name LIKE CONCAT('%', #{assetName}, '%')
AND ai.category_id = #{categoryId}
AND ac3.parent_id = #{level2Id}
AND ac2.parent_id = #{level1Id}
AND ai.status = #{status}
ORDER BY ai.asset_code

